CREATE TABLE IF NOT EXISTS users (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE,
 phone TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'customer' CHECK(role IN ('customer','admin')),
 verified INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS challenges (email TEXT NOT NULL,purpose TEXT NOT NULL,token_hash TEXT NOT NULL,expires_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(email,purpose));
CREATE TABLE IF NOT EXISTS outbox (id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL,subject TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_outbox_email ON outbox(email,id);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS products (
 id TEXT PRIMARY KEY,sku TEXT NOT NULL UNIQUE,name TEXT NOT NULL,brand TEXT NOT NULL,category TEXT NOT NULL,
 weight TEXT NOT NULL,description TEXT NOT NULL,ingredients TEXT NOT NULL,allergens TEXT NOT NULL,image TEXT NOT NULL,
 price INTEGER NOT NULL CHECK(price>=1),mrp INTEGER NOT NULL CHECK(mrp>=price),cost INTEGER NOT NULL DEFAULT 0 CHECK(cost>=0),
 stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0),reorder_level INTEGER NOT NULL DEFAULT 10 CHECK(reorder_level>=0),
 active INTEGER NOT NULL DEFAULT 1,featured INTEGER NOT NULL DEFAULT 0,color TEXT NOT NULL DEFAULT 'sand',
 tax_bps INTEGER NOT NULL DEFAULT 1800 CHECK(tax_bps>=0 AND tax_bps<=10000),version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_products_active_category ON products(active,category);
CREATE TABLE IF NOT EXISTS batches (id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),lot TEXT NOT NULL,supplier TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>=0),expires_on TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_batches_product_expiry ON batches(product_id,expires_on);
CREATE TABLE IF NOT EXISTS stock_movements (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id TEXT NOT NULL REFERENCES products(id),delta INTEGER NOT NULL,reason TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS carts (id TEXT PRIMARY KEY,user_id TEXT UNIQUE REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cart_items (cart_id TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 99),PRIMARY KEY(cart_id,product_id));
CREATE TABLE IF NOT EXISTS wishlist (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,product_id TEXT NOT NULL REFERENCES products(id),PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS addresses (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,phone TEXT NOT NULL,line1 TEXT NOT NULL,line2 TEXT NOT NULL DEFAULT '',area TEXT NOT NULL,pincode TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_addresses_user ON addresses(user_id);
CREATE TABLE IF NOT EXISTS coupons (code TEXT PRIMARY KEY,percent INTEGER NOT NULL CHECK(percent BETWEEN 1 AND 80),min_total INTEGER NOT NULL DEFAULT 0,max_discount INTEGER NOT NULL,usage_limit INTEGER NOT NULL DEFAULT 100,active INTEGER NOT NULL DEFAULT 1,expires_on TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders (
 id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL CHECK(status IN ('confirmed','packing','shipped','delivered','cancelled','refunded')),
 payment_method TEXT NOT NULL,payment_status TEXT NOT NULL DEFAULT 'test_paid',subtotal INTEGER NOT NULL,discount INTEGER NOT NULL,shipping INTEGER NOT NULL,tax INTEGER NOT NULL,total INTEGER NOT NULL,
 coupon TEXT,shipping_address TEXT NOT NULL,gift_note TEXT NOT NULL DEFAULT '',tracking TEXT NOT NULL DEFAULT '',idempotency_key TEXT NOT NULL UNIQUE,
 request_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_orders_user_created ON orders(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);
CREATE TABLE IF NOT EXISTS order_items (id INTEGER PRIMARY KEY AUTOINCREMENT,order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL REFERENCES products(id),name TEXT NOT NULL,sku TEXT NOT NULL,weight TEXT NOT NULL,image TEXT NOT NULL,quantity INTEGER NOT NULL,price INTEGER NOT NULL,tax_bps INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_order_items_order ON order_items(order_id);
CREATE TABLE IF NOT EXISTS order_allocations (order_id TEXT NOT NULL REFERENCES orders(id),batch_id TEXT NOT NULL REFERENCES batches(id),quantity INTEGER NOT NULL,PRIMARY KEY(order_id,batch_id));
CREATE TABLE IF NOT EXISTS returns (id TEXT PRIMARY KEY,order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','approved','declined')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),product_id TEXT NOT NULL REFERENCES products(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
